    /**
     * Tests getting all CommandDefinitions.
     *
     * @return    Collection
     */
    public List<CommandDefinition> testGetAll() throws Throwable {
    LOGGER.info( "CommandDefinitionTest:testGetAll() - Retrieving Collection of CommandDefinitions:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all CommandDefinition : " );
    List<CommandDefinition> collection  = null;

    try {
        // call the static get method on the CommandDefinitionService
        collection = service.getAllCommandDefinition();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            CommandDefinition currEntity  = null;
            Iterator<CommandDefinition> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCommandDefinitionId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

